<script>
import Pager from '@/components/Common/Pager.vue';
import DataService from '../../service/DataService';

export default {
    name: 'ProductLifeCycleHistory',
    components: {
        Pager
    },
    props: {
        show: {
            type: Boolean,
            default: false
        },
        ItemDetails: {
            type: Object,
            default: () => ({})
        }
    },
    computed: {
        assetDetails() {
            const item = this.ItemDetails || {};
            return {
                productType: item.asset_type,
                productName: item.asset_catalogue_id,
                uniqueAssetName: item.unique_name || "",
                serialNumber: item.serial_number || "",
                quantity: item.total_quantity || "",
                currentLocation: item.location_id || "",
                assignedTo: item.assigned_to || "",
                purchaseDate: item.purchase_date || item.acquisition_date || ""
            };
        }

    },
    mounted() {
        this.fetchActivitiesLogs();
    },

    data() {
        return {
            activeTab: 'overview',


            activities: [],

            isAssignmentsVisible: false,
            assignments: [],
            assignmentsTotalRecords: 0,
            assignmentsCurrentPage: 1,
            assignmentsPageSize: 10,

            isTransfersVisible: false,
            transfers: [],
            transfersTotalRecords: 0,
            transfersCurrentPage: 1,
            transfersPageSize: 10,

            searchFromLocation: '',
            searchToLocation: '',
            searchTransferDate: '',
            searchApprovedBy: '',

            isUploadsVisible: true,
            uploads: [],

            uploadsTotalRecords: 1,
            uploadsCurrentPage: 1,

            isAuditsVisible: false,
            audits: [],
            auditsTotalRecords: 0,
            auditsCurrentPage: 1,
            auditsPageSize: 10,
            updateActivities: [],
            pageSize: 10,
            pageNumber: 1


        };
    },
    watch: {
        activeTab(newTab) {
            if (newTab === 'assignments') {
                this.fetchAssignments();
            } else if (newTab === 'transfers') {
                this.fetchTransfers();
            }
            else if (newTab === 'uploads') {
                this.fetchUpdateActivitiesLogs();
            }
            else if (newTab === 'audits') {
                this.fetchAudits();
            }
        }
    },

    methods: {

        closeModal() {
            this.$parent.IsViewHistory = false;
        },

        fetchUpdateActivitiesLogs() {
            if (!this.ItemDetails?.asset_catalogue_id1 || !this.ItemDetails?.related_info_id) {
                return;
            }

            const params = {
                assetCatalogueId: this.ItemDetails.asset_catalogue_id1,
                relatedInfoId: this.ItemDetails.related_info_id
            };

            DataService.GetAssetUpdateActivity(params)
                .then(response => {
                    let list = response.data.activities || [];

                    this.updateActivities = list
                        .filter(item =>
                            item.changed_data !== null &&
                            item.modified_by &&
                            item.modified_by.trim() !== ""

                        )
                        .map(item => {
                            let changes = [];

                            try {
                                const parsed = JSON.parse(item.changed_data);

                                parsed.forEach(x => {
                                    let v = JSON.parse(x.value);

                                    changes.push({
                                        key: x.key,
                                        old: v.old || "",
                                        new: v.new || ""
                                    });
                                });

                            } catch (e) {
                                console.error("JSON parse error", e);
                            }

                            return {
                                ...item,
                                changed: changes,
                                show: false
                            };
                        });
                    this.uploadsTotalRecords = this.updateActivities.length;

                })
                .catch(err => {
                    console.error('GetAssetUpdateActivity error', err);
                });
        },



        fetchActivitiesLogs() {
            if (!this.ItemDetails?.asset_catalogue_id1 || !this.ItemDetails?.related_info_id) {
                return;
            }

            const params = {
                assetCatalogueId: this.ItemDetails.asset_catalogue_id1,
                relatedInfoId: this.ItemDetails.related_info_id,
                histType: 'Audit'
            };

            DataService.GetAssetActivity(params)
                .then(response => {
                    this.activities = response.data.activities || [];
                })
                .catch(err => {
                    console.error('GetAssetActivity error', err);
                })
                .finally(() => {
                    //
                });
        },



        getApiParams(eventTypes, pageNumber, pageSize) {
            return {
                assetCatalogueId: this.ItemDetails.asset_catalogue_id1 || null,
                relatedInfoId: this.ItemDetails.related_info_id || null,
                eventTypes: eventTypes,
                histType: null,
                pageNumber: pageNumber,
                pageSize: pageSize,
                sortBy: "event_date",
                sortDirection: "DESC"
            };
        },

        fetchAssignments() {
            const vm = this;
            const params = vm.getApiParams("Assignment", vm.pageNumber, vm.pageSize);

            DataService.GetLifecycleHistory(params).then(response => {
                if (response.data != null && response.data.length > 0) {
                    vm.assignments = response.data.map(item => ({
                        assignedTo: item.issueTo || "",
                        assignmentDate: item.event_date || "",
                        assignedBy: item.issueBy || "",
                        quantity: item.number_of_items_assigned,
                        status: item.event_type || "",
                        notes: item.description || ""
                    }));
                    vm.assignmentsTotalRecords = response.data[0].TotalRecords || response.data.length;
                    vm.isAssignmentsVisible = true;
                } else {
                    vm.assignments = [];
                    vm.assignmentsTotalRecords = 0;
                    vm.isAssignmentsVisible = false;
                }
            }).catch(error => {
                console.error("Error fetching assignment history:", error);
                vm.assignments = [];
                vm.isAssignmentsVisible = false;
            });
        },

        fetchTransfers() {
            const vm = this;
            const params = vm.getApiParams("Transfer", vm.pageNumber, vm.pageSize);

            DataService.GetLifecycleHistory(params).then(response => {
                if (response.data != null && response.data.length > 0) {
                    vm.transfers = response.data.map(item => ({
                        fromLocation: item.locationFrom || "",
                        toLocation: item.locationTo || "",
                        transferDate: item.event_date || "",
                        approvedBy: item.transfer_by || "",
                        status: item.status_name || "",
                        quantity: item.total_transfer_quantity || "",
                        notes: item.description || ""
                    }));
                    vm.transfersTotalRecords = response.data[0].TotalRecords || response.data.length;
                    vm.isTransfersVisible = true;
                } else {
                    vm.transfers = [];
                    vm.transfersTotalRecords = 0;
                    vm.isTransfersVisible = false;
                }
            }).catch(error => {
                console.error("Error fetching transfer history:", error);
                vm.transfers = [];
                vm.isTransfersVisible = false;
            });
        },

        fetchAudits() {
            const vm = this;
            const params = vm.getApiParams("Audit", vm.pageNumber, vm.pageSize);

            DataService.GetLifecycleHistory(params).then(response => {
                if (response.data != null && response.data.length > 0) {
                    vm.audits = response.data.map(item => ({
                        auditDate: item.event_date || "",
                        auditedBy: item.audit_by || "",
                        result: item.status_name || "",
                        notes: item.description || ""
                    }));
                    vm.auditsTotalRecords = response.data[0].TotalRecords || response.data.length;
                    vm.isAuditsVisible = true;
                } else {
                    vm.audits = [];
                    vm.auditsTotalRecords = 0;
                    vm.isAuditsVisible = false;
                }
            }).catch(error => {
                console.error("Error fetching audit history:", error);
                vm.audits = [];
                vm.isAuditsVisible = false;
            });
        },

        pagerMethodAssignments(page) {
            this.pageSize = page.PageSize;
            this.pageNumber = page.PageNumber;
            this.fetchAssignments();
        },

        pagerMethodTransfers(page) {
            this.pageSize = page.PageSize;
            this.pageNumber = page.PageNumber;
            this.fetchTransfers();
        },

        pagerMethodUploads(page) {
            debugger;
            //  this.pageSize = page.PageSize;
            //  this.pageNumber = page.PageNumber;
            //  this.fetchUpdateActivitiesLogs();
            // this.$parent.ShowsearchData(value);
            // this.uploadsCurrentPage = page.PageSize;
        },

        pagerMethodAudits(page) {
            this.auditsCurrentPage = page;
            this.fetchAudits();
        },
        statusClass(status) {
            switch (status) {
                case 'Deleted':
                    return 'btn-danger';
                case 'In-Transit':
                    return 'btn-info';
                case 'Active':
                    return 'btn-success';
                default:
                    return 'btn-secondary';
            }
        },
        statusLabel(status) {
            switch (status) {
                case 'Active':
                    return 'Active';
                case 'In-Transit':
                    return 'In Transit';    // pretty label
                case 'Deleted':
                    return 'Rejected';      // show as Rejected
                default:
                    return status || 'Unknown';
            }
        },

        // new for assignment status
        assignmentStatusClass(status) {
            switch (status) {
                case 'Assigned':
                    return 'btn-primary';   // blue
                case 'Return':
                    return 'btn-danger';    // red
                case 'Shared':
                    return 'btn-success';   // green
                default:
                    return 'btn-secondary';
            }
        }

    }
};
</script>



